// DTO projection: một query, chỉ lấy đúng thứ màn hình cần
public interface OrderRepository extends JpaRepository<Order, Long> {
    @Query("""
        select new com.example.order.OrderSummary(o.id, c.name, size(o.items))
        from Order o join o.customer c
        order by o.createdAt desc
        """)
    List<OrderSummary> findRecentSummaries(Pageable page);
}

@GetMapping("/orders/recent")
public List<OrderSummary> recent() {
    return orderRepository.findRecentSummaries(PageRequest.of(0, 50));
}

